import { NavigationConfig, parseWorkReference, returnDestination } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsErrorKind(action: () => void, kind: 'URIError' | 'TypeError', message: string): void {
  try { action(); } catch (error) {
    if (kind === 'URIError' ? error instanceof URIError : error instanceof TypeError) return;
    throw new Error(`${message}: wrong error`);
  }
  throw new Error(`${message}: did not throw`);
}

const config: NavigationConfig = { mockMode: false, caseDeskUrl: '  /cases  ', messageDeskUrl: ' /messages ' };
let reference = parseWorkReference('?message=m-1&case=c-1', config);
equal(reference.kind, 'case', 'case takes precedence regardless of order');
equal(reference.id, 'c-1', 'case id is returned');
reference = parseWorkReference('case=%20%20&message=first&message=second', config);
equal(reference.kind, 'message', 'blank case is ignored');
equal(reference.id, 'first', 'first nonempty duplicate value is used');
reference = parseWorkReference('case=&case=+trimmed+&case=later', config);
equal(reference.kind, 'case', 'later nonempty duplicate is considered');
equal(reference.id, 'trimmed', 'plus is decoded as space and result is trimmed');
reference = parseWorkReference('ignored=a=b&ca%73e=value%3Dpart', config);
equal(reference.id, 'value=part', 'pair splits at first equals and percent escapes decode');

throwsErrorKind(() => parseWorkReference('', config), 'URIError', 'empty query without mock reference');
throwsErrorKind(() => parseWorkReference('other=value', config), 'URIError', 'missing work reference');
throwsErrorKind(() => parseWorkReference('case=%ZZ', config), 'URIError', 'malformed value escape');
throwsErrorKind(() => parseWorkReference('%ZZ=x&case=valid', config), 'URIError', 'malformed name escape propagates');

const mock = parseWorkReference('%ZZ', { mockMode: true, caseDeskUrl: '', messageDeskUrl: '' });
equal(mock.kind, 'case', 'mock mode bypasses parsing');
equal(mock.id, 'sample-case', 'mock mode uses sample id');

const messageDestination = returnDestination('  msg  ', config);
equal(messageDestination.text, 'Message desk', 'nonblank message selects message desk');
equal(messageDestination.url, '/messages', 'selected message URL is trimmed');
const caseDestination = returnDestination('  ', config);
equal(caseDestination.text, 'Case desk', 'blank message selects case desk');
equal(caseDestination.url, '/cases', 'selected case URL is trimmed');
equal(returnDestination(undefined, config).text, 'Case desk', 'undefined message selects case desk');

const mutableConfig = { mockMode: false, caseDeskUrl: ' /original ', messageDeskUrl: '/m' };
const destination = returnDestination(undefined, mutableConfig);
mutableConfig.caseDeskUrl = '/changed';
equal(destination.url, '/original', 'destination does not retain configuration data');
throwsErrorKind(() => returnDestination(undefined, { ...config, caseDeskUrl: '  ' }), 'TypeError', 'blank selected case URL');
throwsErrorKind(() => returnDestination('x', { ...config, messageDeskUrl: '\t' }), 'TypeError', 'blank selected message URL');
assert(config.caseDeskUrl === '  /cases  ', 'configuration is not mutated');

